/**
 * Static curriculum: 3 stages → 15 levels → 3 lessons each.
 * Lessons with a `gen` produce problems locally (instant, no AI needed);
 * the rest get quiz/problems generated by the AI tutor.
 */

export type StageId = "beginner" | "advanced" | "expert";

export type Problem = {
  question: string; // markdown + $LaTeX$
  answer: string; // canonical answer, checked by `checkAnswer`
  hint?: string;
};

export type Lesson = {
  id: string;
  title: string;
  theory: string;
  free?: boolean;
  gen?: () => Problem;
};

export type Level = { number: number; title: string; description: string; lessons: Lesson[] };
export type Stage = { id: StageId; title: string; subtitle: string; levels: Level[] };

const r = (a: number, b: number) => Math.floor(Math.random() * (b - a + 1)) + a;
const pick = <T,>(xs: T[]) => xs[r(0, xs.length - 1)];
const gcd = (a: number, b: number): number => (b === 0 ? Math.abs(a) : gcd(b, a % b));
const frac = (n: number, d: number) => {
  const g = gcd(n, d);
  const [nn, dd] = [n / g, d / g];
  return dd === 1 ? String(nn) : `${nn}/${dd}`;
};

