// ---------------------------------------------------------------- Lookups
export type LessonRef = { lesson: Lesson; level: Level; stage: Stage };

export const ALL_LESSONS: LessonRef[] = STAGES.flatMap((stage) =>
  stage.levels.flatMap((level) => level.lessons.map((lesson) => ({ lesson, level, stage }))),
);

export function findLesson(id: string): LessonRef | undefined {
  return ALL_LESSONS.find((x) => x.lesson.id === id);
}

export const FREE_LESSON_IDS = ALL_LESSONS.filter((x) => x.lesson.free).map((x) => x.lesson.id);

export function canAccessLesson(lessonId: string, pro: boolean): boolean {
  return pro || FREE_LESSON_IDS.includes(lessonId);
}

// ---------------------------------------------------------------- Answer checking
function toNumber(s: string): number | null {
  const t = s.trim().replace(/\s+/g, "").replace(",", ".").replace(/^\+/, "");
  if (/^-?\d+(\.\d+)?$/.test(t)) return Number(t);
  const m = t.match(/^(-?\d+)\/(-?\d+)$/);
  if (m && Number(m[2]) !== 0) return Number(m[1]) / Number(m[2]);
  return null;
}

/** Deterministic check used for the Free plan and for locally generated problems. */
export function checkAnswer(given: string, expected: string): boolean {
  const a = toNumber(given);
  const b = toNumber(expected);
  if (a !== null && b !== null) return Math.abs(a - b) < 1e-6;
  const norm = (s: string) => s.trim().toLowerCase().replace(/\s+/g, "").replace(/^x=/, "");
  return norm(given) === norm(expected);
}

/** Build a multiple-choice question from a locally generated problem. */
export function toMultipleChoice(p: Problem): { question: string; options: string[]; answer: string } {
  const n = toNumber(p.answer);
  const options = new Set([p.answer]);
  if (n !== null && Number.isInteger(n)) {
    const deltas = [1, -1, 2, -2, 10, -10, 5, -5].sort(() => Math.random() - 0.5);
    for (const d of deltas) {
      if (options.size >= 4) break;
      if (n + d >= 0 || n < 0) options.add(String(n + d));
    }
  } else if (p.answer.includes("/")) {
    const [nu, de] = p.answer.split("/").map(Number);
    for (const cand of [`${nu + 1}/${de}`, `${nu}/${de + 1}`, `${Math.max(1, nu - 1)}/${de}`, `${de}/${nu}`]) {
      if (options.size >= 4) break;
      options.add(cand);
    }
  } else if (n !== null) {
    for (const k of [0.1, -0.1, 1, -1]) {
      if (options.size >= 4) break;
      options.add(String(Math.round((n + k) * 100) / 100));
    }
  }
  return { question: p.question, options: [...options].sort(() => Math.random() - 0.5), answer: p.answer };
}
